 76	    private static final class Graph {
 77	        private final List<List<Edge>> adjacency;
 78	
 79	        private Graph(List<List<Edge>> adjacency) {
 80	            this.adjacency = adjacency;
 81	        }
 82	
 83	        static Graph withVertexCount(int vertexCount) {
 84	            if (vertexCount < 0) {
 85	                throw new IllegalArgumentException("vertexCount must be non-negative");
 86	            }
 87	
 88	            List<List<Edge>> adjacency = new ArrayList<>(vertexCount);
 89	            for (int i = 0; i < vertexCount; i++) {
 90	                adjacency.add(new ArrayList<>());
 91	            }
