143	        boolean isStale(QueueEntry entry) {
144	            return entry.distance > values[entry.vertex];
145	        }
146	
147	        boolean tryUpdate(int vertex, int distance) {
148	            if (distance >= values[vertex]) {
149	                return false;
150	            }
151	
152	            values[vertex] = distance;
153	            return true;
154	        }
