165	    private static final class ShortestPathSolver {
166	        private final Graph graph;
167	        private final Distances distances;
168	        private final PriorityQueue<QueueEntry> minHeap;
169	
170	        private ShortestPathSolver(Graph graph, int source) {
171	            if (graph == null) {
172	                throw new IllegalArgumentException("graph must not be null");
173	            }
174	            this.graph = graph;
175	            this.distances = Distances.forSource(graph.vertexCount(), source);
176	            this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
177	            this.minHeap.offer(new QueueEntry(source, 0));
178	        }
179	
180	        static Distances solve(Graph graph, int source) {
181	            return new ShortestPathSolver(graph, source).run();
182	        }
183	
184	        private Distances run() {
185	            while (!minHeap.isEmpty()) {
186	                QueueEntry current = minHeap.poll();
187	                if (distances.isStale(current)) {
188	                    continue;
189	                }
190	                relaxNeighborsOf(current);
191	            }
192	            return distances;
193	        }
194	
195	        private void relaxNeighborsOf(QueueEntry current) {
196	            for (Edge edge : graph.neighborsOf(current.vertex)) {
197	                tryRelax(current, edge);
198	            }
199	        }
200	
201	        private void tryRelax(QueueEntry current, Edge edge) {
202	            if (current.distance == Integer.MAX_VALUE) {
203	                return;
204	            }
205	
206	            long candidateDistance = (long) current.distance + edge.weight;
207	            if (candidateDistance > Integer.MAX_VALUE) {
208	                return;
209	            }
210	
211	            if (distances.tryUpdate(edge.to, (int) candidateDistance)) {
212	                minHeap.offer(new QueueEntry(edge.to, (int) candidateDistance));
213	            }
214	        }
215	    }
